 1→import type { ScenarioContent } from "../../core/scenario-api.service";
 2→
 3→export interface ScenarioExport {
 4→  title: string;
 5→  description: string;
 6→  content: ScenarioContent;
 7→}
 8→
 9→export function exportScenarioToJson(
10→  title: string,
11→  description: string,
12→  content: ScenarioContent,
13→): Blob {
14→  const data: ScenarioExport = { title, description, content };
15→  return new Blob([JSON.stringify(data, null, 2)], {
16→    type: "application/json",
17→  });
18→}
19→
20→export function parseScenarioImport(jsonString: string): ScenarioExport | null {
21→  let parsed: unknown;
22→  try {
23→    parsed = JSON.parse(jsonString);
24→  } catch {
25→    return null;
26→  }
27→  if (typeof parsed !== "object" || parsed === null) return null;
28→  // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- narrowed by typeof check above
29→  const obj = parsed as Record<string, unknown>;
30→  if (typeof obj["title"] !== "string") return null;
31→  if (typeof obj["content"] !== "object" || obj["content"] === null)
32→    return null;
33→  return {
34→    title: obj["title"],
35→    description:
36→      typeof obj["description"] === "string" ? obj["description"] : "",
37→    // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion -- validated above
38→    content: obj["content"] as ScenarioContent,
39→  };
40→}
